<template><ToolShell :eyebrow="label('No-side-effect sandbox', 'Sandbox sin efectos')" :title="label('Preview API behavior', 'Previsualiza el comportamiento de la API')" :description="label('Generate fixture responses and code examples without credentials, billing or real email delivery.', 'Genera respuestas simuladas y ejemplos sin credenciales, facturación ni envío real.')"><form class="stack" @submit.prevent="run"><BaseSelect id="sandbox-scenario" v-model="scenario" name="scenario" :label="label('Scenario', 'Escenario')" :options="options" /><BaseSelect id="sandbox-language" v-model="language" name="language" :label="label('Code language', 'Lenguaje del código')" :options="languages" /><BaseButton type="submit" :disabled="pending">{{ label('Run simulation', 'Ejecutar simulación') }}</BaseButton><BaseAlert v-if="errorMessage" tone="danger">{{ errorMessage }}</BaseAlert><div v-if="result" class="stack"><BaseAlert tone="info">{{ label('No email was sent.', 'No se envió ningún correo.') }} {{ result.message.state }}</BaseAlert><pre><code>{{ codeExample }}</code></pre></div></form></ToolShell></template>
<script setup lang="ts">interface Result{sent:boolean;message:{id:string;state:string}}const{locale}=useLocale();const label=(en:string,es:string)=>locale.value==='es'?es:en;const scenario=ref('accepted');const language=ref('curl');const options=computed(()=>['accepted','deferred','bounced','complained'].map(value=>({value,label:value})));const languages=computed(()=>['curl','typescript','python','php'].map(value=>({value,label:value})));const result=ref<Result>();const{pending,errorMessage,execute}=useToolRequest();const run=async()=>{result.value=await execute<Result>('/api/v1/tools/api-sandbox',{scenario:scenario.value})};const codeExample=computed(()=>{const key='kly_test_xxxxxxxxx';const samples:Record<string,string>={curl:`curl -X POST https://api.klyrow.com/v1/messages -H "Authorization: Bearer ${key}" -d '{"to":"recipient@example.com"}'`,typescript:`await fetch('https://api.klyrow.com/v1/messages', { method: 'POST', headers: { Authorization: 'Bearer ${key}' } })`,python:`requests.post('https://api.klyrow.com/v1/messages', headers={'Authorization': 'Bearer ${key}'})`,php:`$client->post('https://api.klyrow.com/v1/messages', ['headers' => ['Authorization' => 'Bearer ${key}']]);`};return samples[language.value]??samples.curl})</script>
<style scoped>pre{overflow:auto;padding:1rem;border-radius:var(--radius-md);background:#111326;color:#e8e9ff}</style>
